from pathlib import Path
import subprocess, sys, json
WORKDIR = Path('/tmp/ringer-baldev75')
sa = WORKDIR / 'stayin_alive_slideshow.mp4'
fl = WORKDIR / 'full_life_slideshow.mp4'
for f in (sa, fl):
    if not f.exists():
        print(f'WHY: {f.name} was not built (worker must run build_slideshows.py to produce it)'); sys.exit(1)
    if f.stat().st_size < 5_000_000:
        print(f'WHY: {f.name} is only {f.stat().st_size} bytes (expected >5MB)'); sys.exit(1)
def probe(p):
    r = subprocess.run(['ffprobe','-v','quiet','-print_format','json','-show_streams','-show_format',str(p)], capture_output=True, text=True)
    return json.loads(r.stdout) if r.returncode == 0 else None
for name, f, dur_lo, dur_hi in [('stayin_alive', sa, 280, 400), ('full_life', fl, 500, 1000)]:
    info = probe(f)
    if not info:
        print(f'WHY: ffprobe cannot read {f.name} - not a valid video'); sys.exit(1)
    vstreams = [s for s in info.get('streams',[]) if s.get('codec_type')=='video']
    if not vstreams:
        print(f'WHY: {f.name} has no video stream'); sys.exit(1)
    dur = float(info.get('format',{}).get('duration', 0))
    if not (dur_lo <= dur <= dur_hi):
        print(f'WHY: {f.name} duration {dur:.0f}s outside {dur_lo}-{dur_hi}s'); sys.exit(1)
    w = int(vstreams[0].get('width',0)); h = int(vstreams[0].get('height',0))
    if w < 1280 or h < 720:
        print(f'WHY: {f.name} {w}x{h} below 720p'); sys.exit(1)
    print(f'  {name}: {dur:.0f}s, {w}x{h}, {f.stat().st_size//1_000_000}MB')
print('PASS: both slideshows verified via ffprobe (valid HD video, correct durations)')
